/** Formats a KPI value. (Rendered statically: a client-side count-up visibly flashed the number to 0 after hydration.) */
export function CountUp({ value, kind }: { value: number; kind: "inr" | "int" | "pct" }) {
  const text =
    kind === "inr"
      ? new Intl.NumberFormat("en-IN", { style: "currency", currency: "INR", maximumFractionDigits: 0 }).format(value / 100)
      : kind === "pct"
        ? `${value.toFixed(value < 10 ? 2 : 1)}%`
        : Math.round(value).toLocaleString("en-IN");
  return <span className="tabular-nums">{text}</span>;
}
