import { ArrowDownRight, ArrowUpRight } from "lucide-react";
import { CountUp } from "./CountUp";
import { cn } from "@/lib/utils";

export function PageHeader({ title, description, actions }: { title: string; description?: string; actions?: React.ReactNode }) {
  return (
    <div className="mb-6 flex flex-wrap items-end justify-between gap-3">
      <div>
        <h1 className="font-display text-3xl font-semibold">{title}</h1>
        {description && <p className="mt-1 text-sm text-muted">{description}</p>}
      </div>
      {actions && <div className="flex flex-wrap gap-2">{actions}</div>}
    </div>
  );
}

export function Panel({ title, children, className, action }: { title?: string; children: React.ReactNode; className?: string; action?: React.ReactNode }) {
  return (
    <section className={cn("animate-fade-up rounded-lg border border-line bg-white p-5", className)}>
      {(title || action) && (
        <div className="mb-4 flex items-center justify-between gap-2">
          {title && <h2 className="font-semibold">{title}</h2>}
          {action}
        </div>
      )}
      {children}
    </section>
  );
}

/** KPI stat tile: the number is the chart. Change vs previous period carries an icon, not color alone. */
export function StatTile({ label, value, change, hint, delay = 0 }: { label: string; value: { n: number; kind: "inr" | "int" | "pct" }; change?: number | null; hint?: string; delay?: number }) {
  const up = (change ?? 0) >= 0;
  return (
    <div className="animate-fade-up rounded-lg border border-line bg-white p-4 transition hover:-translate-y-0.5 hover:shadow-md" style={{ animationDelay: `${delay}ms` }}>
      <p className="text-xs font-medium uppercase tracking-wide text-muted">{label}</p>
      <p className="mt-1 text-2xl font-semibold"><CountUp value={value.n} kind={value.kind} /></p>
      {change !== undefined && change !== null ? (
        <p className={cn("mt-1 flex items-center gap-0.5 text-xs font-medium", up ? "text-success" : "text-danger")}>
          {up ? <ArrowUpRight className="h-3.5 w-3.5" aria-hidden /> : <ArrowDownRight className="h-3.5 w-3.5" aria-hidden />}
          {up ? "+" : ""}{change.toFixed(1)}% <span className="font-normal text-muted">vs previous period</span>
        </p>
      ) : (
        hint && <p className="mt-1 text-xs text-muted">{hint}</p>
      )}
    </div>
  );
}

export function Table({ head, children }: { head: React.ReactNode[]; children: React.ReactNode }) {
  return (
    <div className="overflow-x-auto">
      <table className="w-full text-sm">
        <thead>
          <tr className="border-b border-line text-left text-xs uppercase tracking-wide text-muted">
            {head.map((h, i) => <th key={i} className="whitespace-nowrap px-3 py-2 font-medium">{h}</th>)}
          </tr>
        </thead>
        <tbody className="divide-y divide-line/70 [&>tr]:transition-colors [&>tr:hover]:bg-paper/70">{children}</tbody>
      </table>
    </div>
  );
}

export const td = "px-3 py-2.5 align-middle";
